def parse_report(output):
    """Pull the printed license-report.json object out of the act log."""
    m = re.search(r"----- license-report\.json -----\s*(\{.*?\n\})",
                  output, re.DOTALL)
    if not m:
        return None
    # The act log prefixes each line with the job name; strip those prefixes.
    raw = re.sub(r"^.*?\|\s?", "", m.group(1), flags=re.MULTILINE)
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return None

